package com.examforge.grading;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;import com.examforge.common.*;import com.examforge.common.ApiDtos.*;import com.examforge.attempt.*;import com.examforge.attempt.entity.*;import com.examforge.attempt.mapper.*;import com.examforge.grading.entity.*;import com.examforge.grading.mapper.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.BigDecimal;import java.time.LocalDateTime;import java.util.*;
@Service public class GradingService{
 private final ExamAttemptService attemptService;private final ExamAttemptMapper attempts;private final AnswerRecordMapper answers;private final GradeResultMapper grades;
 public GradingService(ExamAttemptService a,ExamAttemptMapper am,AnswerRecordMapper ar,GradeResultMapper g){attemptService=a;attempts=am;answers=ar;grades=g;}
 @Transactional public void grade(Long attemptId){ExamAttemptEntity a=attempts.selectById(attemptId);if(a==null||!"SUBMITTED".equals(a.getStatus())||grades.selectByAttemptId(attemptId)!=null)return;Map<Long,AnswerRecordEntity> map=new HashMap<>();for(var q:attemptService.snapshot(a)){answers.insertIfAbsent(attemptId,q.questionId());AnswerRecordEntity ar=answers.selectForUpdate(attemptId,q.questionId());map.put(q.questionId(),ar);}BigDecimal objective=BigDecimal.ZERO;boolean pending=false;
  for(var q:attemptService.snapshot(a)){AnswerRecordEntity ar=map.get(q.questionId());if("SUBJECTIVE".equals(q.type())){pending=true;continue;}boolean correct="MULTIPLE".equals(q.type())?normalizeMulti(ar.getAnswer()).equals(normalizeMulti(q.correctAnswer())):normalize(ar.getAnswer()).equals(normalize(q.correctAnswer()));BigDecimal score=correct?q.score():BigDecimal.ZERO;ar.setScore(score);answers.updateById(ar);objective=objective.add(score);}
  GradeResultEntity g=new GradeResultEntity();g.setAttemptId(attemptId);g.setExamId(a.getExamId());g.setUserId(a.getUserId());g.setObjectiveScore(objective);g.setSubjectiveScore(BigDecimal.ZERO);g.setTotalScore(objective);g.setStatus(pending?"PENDING_MANUAL":"COMPLETED");g.setGradedAt(LocalDateTime.now());g.setUpdateTime(LocalDateTime.now());grades.insert(g);
 }
 @Transactional public ResultView manualGrade(Long attemptId,ManualGradeRequest req){GradeResultEntity g=grades.selectByAttemptId(attemptId);if(g==null)throw new BusinessException("阅卷任务尚未生成");if(!"PENDING_MANUAL".equals(g.getStatus()))throw new BusinessException("该试卷无需人工阅卷或已完成");ExamAttemptEntity a=attempts.selectById(attemptId);Map<Long,ExamAttemptService.SnapshotQuestion> qs=new HashMap<>();for(var q:attemptService.snapshot(a))qs.put(q.questionId(),q);
  for(SubjectiveScore s:req.scores()){var q=qs.get(s.questionId());if(q==null||!"SUBJECTIVE".equals(q.type()))throw new BusinessException("人工评分题目无效："+s.questionId());if(s.score().compareTo(q.score())>0)throw new BusinessException("题目得分不能超过满分");AnswerRecordEntity ar=answers.selectOne(new LambdaQueryWrapper<AnswerRecordEntity>().eq(AnswerRecordEntity::getAttemptId,attemptId).eq(AnswerRecordEntity::getQuestionId,s.questionId()));if(ar==null)throw new BusinessException("答题记录不存在");ar.setScore(s.score());ar.setTeacherComment(s.comment());answers.updateById(ar);}
  BigDecimal subjective=BigDecimal.ZERO;for(var q:qs.values())if("SUBJECTIVE".equals(q.type())){AnswerRecordEntity ar=answers.selectOne(new LambdaQueryWrapper<AnswerRecordEntity>().eq(AnswerRecordEntity::getAttemptId,attemptId).eq(AnswerRecordEntity::getQuestionId,q.questionId()));if(ar==null||ar.getScore()==null)throw new BusinessException("还有主观题未完成评分");subjective=subjective.add(ar.getScore());}
  g.setSubjectiveScore(subjective);g.setTotalScore(g.getObjectiveScore().add(subjective));g.setStatus("COMPLETED");g.setGradedAt(LocalDateTime.now());g.setUpdateTime(LocalDateTime.now());grades.updateById(g);return attemptService.result(attemptId,a.getUserId());
 }
 private String normalize(String s){return s==null?"":s.toUpperCase(Locale.ROOT).replaceAll("[\\s，,;；]","").trim();}
 private String normalizeMulti(String s){if(s==null||s.isBlank())return "";return Arrays.stream(s.toUpperCase(Locale.ROOT).split("[,，;；]" )).map(String::trim).filter(x->!x.isEmpty()).sorted().reduce((a,b)->a+","+b).orElse("");}
}
